export const DATA_26: ReadingTest[] = [
  { id: "rd-032", num: 32, title: "Đề 032", timeMin: 60, parts: [
    { title: "The Rise of Mechanical Guardians in Modern Agriculture", paragraphs: ["Walk through a large modern farm today, and you might notice something that would have seemed like science fiction only twenty years ago: a small wheeled machine slowly moving between rows of crops, pausing occasionally to examine individual plants before rolling on to the next one. These machines, often called agricultural robots, are increasingly taking over tasks that farm workers once had to perform by hand, from checking soil moisture to identifying which plants need extra attention. Farmers who have adopted them describe the change less as replacing human labor entirely and more as gaining a tireless assistant that never gets bored or distracted.", "One of the most common jobs given to these machines is monitoring plant health across a field far too large for one person to check carefully every day. Cameras mounted on the robot capture images of each plant, and software compares these images against patterns learned from thousands of healthy and unhealthy plants photographed previously. When a robot spots a leaf that looks unusually pale or spotted, it marks the exact location so a human worker can inspect that specific plant rather than searching the entire field by hand. This targeted approach means problems can often be caught days earlier than they would be through regular human inspection alone.", "Weeding is another task where these machines have proven especially useful. Traditional weed control often relies on spraying entire fields with chemicals, even though weeds usually grow in scattered, uneven patches rather than everywhere at once. A robot equipped with a camera can instead identify individual weeds among the crops and either pull them mechanically or spray a tiny, precise amount of chemical directly onto that single plant. Farmers using this approach report using noticeably less chemical overall, which lowers costs and reduces the amount of spray that ends up in nearby soil and water.", "Despite these benefits, adopting agricultural robots is not simple or cheap for every farmer. The machines themselves can cost as much as a small tractor, and they require occasional repairs that not every rural area has a technician nearby to handle. Software also needs regular updates to keep recognizing new types of pests or diseases as they appear, meaning a robot bought several years ago may need updating before it works as well as a newer model. Smaller farms, in particular, sometimes struggle to justify the upfront cost when their fields are not large enough to make the labor savings clearly worthwhile.", "Even so, many agricultural experts expect these machines to become far more common over the coming decade, as prices gradually fall and the technology becomes easier for ordinary farmers to operate without specialized training. Some companies have already begun renting robots by the season rather than selling them outright, letting smaller farms try the technology without a large upfront purchase. Whether this rental approach spreads widely enough to bring the benefits to farms of every size remains something the industry is still actively working out."], questions: [{ q: "According to the passage, how does a robot decide which plants a human worker should inspect?", options: ["It marks the location of leaves that look unusually pale or spotted.", "It sprays chemicals directly onto every plant it photographs.", "It randomly selects a few plants from the field each morning.", "It relies entirely on the farmer walking the field personally."], answer: 0 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Agricultural robots are completely replacing all human farm workers.", "Agricultural robots offer real benefits but remain a costly, imperfect option.", "Every farm has already fully adopted robots for weeding and monitoring.", "Chemical weed spraying is now banned on all modern farms."], answer: 1 }, { q: "The word \"monitoring\" in paragraph 2 is closest in meaning to _______.", options: ["watching closely", "removing", "monitor", "planting"], answer: 0 }, { q: "According to the passage, why do farmers using weeding robots report using less chemical overall?", options: ["Weeds usually grow in scattered, uneven patches across a field.", "Robots spray a tiny, precise amount only onto individual weeds.", "Traditional weed control always sprays chemicals across an entire field.", "Farmers using robots have stopped using chemicals of any kind."], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a challenge of adopting agricultural robots?", options: ["The machines can cost as much as a small tractor.", "A shortage of nearby technicians for occasional repairs.", "Software needing regular updates to recognize new pests.", "Government regulations currently banning robots on most farms."], answer: 3 }, { q: "What does the word \"they\" refer to in paragraph 4's phrase about updates keeping software current?", options: ["small tractors", "rural technicians", "pests or diseases", "smaller farms"], answer: 2 }, { q: "According to the passage, why have some companies begun renting robots by the season?", options: ["To let smaller farms try the technology without a large upfront purchase.", "Because prices for agricultural robots have already dropped sharply.", "Because most farms refuse to buy any farm equipment outright.", "To force smaller farms to eventually buy the robots permanently."], answer: 0 }, { q: "The word \"upfront\" in paragraph 4 is closest in meaning to _______.", options: ["paid in advance", "paid monthly", "refundable", "unfair"], answer: 0 }, { q: "What can be inferred about the future of agricultural robots, based on the passage?", options: ["Every farm will be legally required to buy a robot within years.", "They will likely become more common as prices fall and use gets easier.", "Chemical weed spraying will completely disappear within the next year.", "Smaller farms will always struggle to justify the upfront cost."], answer: 1 }, { q: "What is the author's overall attitude toward agricultural robots?", options: ["Cautiously positive, recognizing clear benefits alongside real practical limits.", "Strongly opposed to any use of robots in modern farming.", "Fully convinced robots will replace every human farm worker soon.", "Mostly indifferent to whether farms adopt this new technology."], answer: 0 }] },
    { title: "Mahendraparvata: The Lost City of the Khmer Empire", paragraphs: ["Long before Angkor Wat rose to become the enduring symbol of Khmer civilization, an earlier capital had already flourished and, over subsequent centuries, been reclaimed so completely by the surrounding forest that its very existence survived mainly as fragmentary references in inscriptions rather than as a site anyone could confidently locate on the ground. Mahendraparvata, established in the early ninth century atop a forested plateau, is now understood to have functioned as an early Khmer capital, though for generations its precise location and true scale remained matters of scholarly speculation rather than settled archaeological fact.", "It was airborne laser-scanning technology, more than any single ground excavation, that ultimately transformed Mahendraparvata from a semi-legendary reference into a mapped urban landscape. Conventional ground surveys in dense tropical forest are painstakingly slow, since thick vegetation obscures features that might otherwise be visible from above, and researchers can spend years documenting a fraction of a site that airborne scanning can capture in days. By recording the precise distance to millions of points across the landscape and computationally filtering out vegetation, researchers produced a detailed map of the forest floor revealing a highly organized urban grid that had remained essentially invisible from the ground for centuries.", "This mapping effort revealed a city considerably larger and more systematically planned than earlier ground-based investigations had suggested, including an extensive network of roads, engineered water-management channels, and residential mounds arranged according to a discernible grid rather than scattered without any apparent overall design. The scale of this water infrastructure indicates a level of centralized planning and labor coordination that ground surveys, limited to the small fraction of the site they could physically access, had substantially underestimated for decades.", "Some archaeologists argue that this same water-management system, initially built to support agricultural production and a growing urban population, may eventually have contributed to the city's decline rather than merely sustaining its rise. Maintaining an elaborate network of channels and reservoirs requires sustained coordinated labor and stable governance; should political authority weaken or population pressures shift, the same infrastructure that once enabled prosperity can deteriorate into a source of vulnerability, particularly if extended drought or unusually intense flooding strain a system no longer receiving adequate maintenance.", "Whether Mahendraparvata was ultimately abandoned gradually, as inhabitants and resources shifted toward what later became Angkor, or declined more abruptly due to a specific environmental or political crisis, remains a question the current evidence does not resolve with confidence. [1] Some researchers favor a gradual-transition model, pointing to overlapping occupation periods between the two sites that suggest continuity rather than a sudden, singular collapse. [2] Others note that certain structural and settlement patterns at Mahendraparvata show signs consistent with disruption occurring on a faster timescale than gradual population drift would typically produce. [3] Resolving this disagreement will likely require additional excavation targeted specifically at dating the site's final occupation phases with greater precision. [4]", "The rediscovery of Mahendraparvata has, in turn, prompted researchers to apply similar laser-scanning techniques to other forested regions long suspected of concealing additional archaeological remains, on the reasoning that if a capital city of this scale could remain effectively hidden for centuries, comparable settlements elsewhere in similarly dense terrain may have escaped detection for the very same reason. Several of these subsequent surveys have already identified promising anomalies warranting further ground investigation, though confirming any of them as genuine settlement remains would require the kind of painstaking on-site excavation that laser scanning, for all its advantages, cannot by itself provide.", "Taken together, Mahendraparvata's rediscovery illustrates less a single triumphant breakthrough than a productive partnership between remote-sensing technology and traditional archaeological fieldwork, each compensating for limitations the other cannot resolve on its own. Whether comparably significant discoveries remain hidden beneath forest canopies elsewhere is a question the technology's continued application, rather than any current inventory of known sites, will ultimately have to answer."], questions: [{ q: "According to the passage, why was airborne laser scanning more effective than conventional ground surveys at Mahendraparvata?", options: ["Dense vegetation makes conventional ground surveys extremely slow and limited.", "Ground surveys had already fully mapped the entire site years earlier.", "Airborne scanning requires far more excavation than ground surveys do.", "Conventional surveys work better than airborne scanning in dense forest."], answer: 0 }, { q: "The word \"systematically\" in paragraph 3 is closest in meaning to _______.", options: ["randomly", "in an organized way", "systemically", "temporarily"], answer: 1 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["Ground excavation alone fully revealed Mahendraparvata's true urban scale.", "Angkor Wat was built directly on top of Mahendraparvata's ruins.", "Laser scanning and fieldwork together revealed a far larger lost Khmer city.", "Every forested region in Southeast Asia hides an ancient Khmer capital."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a feature revealed by the mapping effort?", options: ["An extensive network of roads across the site.", "Engineered water-management channels and reservoirs.", "Residential mounds arranged according to a discernible grid.", "A royal palace confirmed through inscriptions found on-site."], answer: 3 }, { q: "According to the passage, how might the water-management system have contributed to the city's decline?", options: ["It required sustained labor and governance that may not have continued.", "It was originally built without any agricultural purpose at all.", "It functioned perfectly regardless of political or environmental conditions.", "It was abandoned immediately after the city's founding centuries earlier."], answer: 0 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This disagreement has not yet been settled by the currently available evidence.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }, { q: "The word \"anomalies\" refers in paragraph 6, in the context of later surveys, most closely to _______.", options: ["confirmed cities", "unusual patterns", "excavation teams", "forest canopies"], answer: 1 }, { q: "According to the passage, what limitation does laser-scanning technology still have, according to the passage?", options: ["It cannot by itself confirm that detected anomalies are genuine settlements.", "It has already fully confirmed every anomaly it has detected.", "It works only in regions without any forest cover at all.", "It requires more time than traditional ground excavation methods."], answer: 0 }, { q: "What can be inferred about future archaeological discoveries in forested regions, based on the passage?", options: ["No further ancient settlements are likely to be found using this technology.", "Ground excavation alone will replace laser scanning going forward.", "Similarly sized settlements may still remain undetected beneath forest canopies.", "Mahendraparvata was established in the early ninth century."], answer: 2 }, { q: "What is the author's overall attitude toward the rediscovery of Mahendraparvata, as conveyed in the passage?", options: ["Impressed by the discovery, while emphasizing genuine remaining uncertainty.", "Fully certain about exactly how and why the city was abandoned.", "Dismissive of laser-scanning technology's actual archaeological value.", "Mostly focused on criticizing earlier ground-based archaeological surveys."], answer: 0 }] },
    { title: "Melodies of the Mind: Music as a Pedagogical Tool", paragraphs: ["Claims that musical training sharpens cognitive faculties well beyond the concert hall have circulated in education policy debates for decades, occasionally hardening into confident public pronouncements that outpace what the underlying research actually supports. The intuitive appeal of such claims is not hard to locate: learning an instrument demands sustained attention, fine motor coordination, and the ability to process multiple layers of information simultaneously, each of which resembles, at least superficially, cognitive demands prized in academic settings far removed from music itself.", "Neuroimaging studies of trained musicians have identified structural differences in regions associated with auditory processing, motor control, and, in some analyses, executive function, differences that appear more pronounced the earlier training began and the longer it continued. Researchers caution, however, that identifying a structural difference is not equivalent to establishing that musical training caused it, since brains capable of sustaining years of disciplined practice may have differed in relevant ways before that practice ever began, a possibility that purely observational neuroimaging cannot, by its nature, rule out on its own.", "This causal ambiguity becomes particularly consequential when evaluating claims of so-called far transfer, the notion that skills developed through musical training generalize to unrelated domains such as mathematics or reading comprehension. Near transfer, improvement on tasks closely resembling the trained skill itself, is comparatively well documented and relatively uncontroversial. Far transfer claims rest on considerably shakier empirical ground: meta-analyses pooling results across dozens of studies have generally found effects too small and too inconsistent across research designs to support the sweeping claims occasionally advanced in popular education literature, even though a minority of well-controlled studies do report modest, domain-specific gains worth further investigation.", "Self-selection compounds this interpretive difficulty considerably. Families that enroll children in years of structured musical instruction typically differ from those that do not along dimensions, including household income, parental educational attainment, and general enrichment access, that independently predict academic performance regardless of any musical training whatsoever. Studies that fail to adequately control for these confounding factors risk attributing to music what more plausibly reflects the broader advantages already present in participating families, meaning apparent correlations between musical training and academic achievement may substantially overstate music's independent causal contribution once these factors are properly accounted for.", "Perhaps no claim illustrates the gap between popular belief and research evidence more starkly than the so-called Mozart effect, the notion that simply listening to classical music temporarily boosts spatial reasoning ability. The original, narrowly scoped 1993 study measuring a brief performance improvement after listening to a specific sonata was, through a chain of media amplification , transformed into a broad public conviction that classical music itself enhances intelligence, a conclusion the original researchers never claimed and that subsequent replication attempts have largely failed to confirm at anything resembling the popularly assumed magnitude.", "Translating even well-supported findings into classroom practice introduces its own complications. [1] Structured approaches such as Kodály and Orff methods emphasize active music-making, rhythm, and ensemble participation rather than passive listening, aligning more closely with what research actually supports than approaches built around background music alone. [2] Implementing these programs well requires trained specialist teachers, adequate instructional time, and instruments, resources that many under-funded schools struggle to sustain even when administrators are otherwise persuaded of the pedagogical case. [3] Music programs consequently remain among the first extracurricular offerings cut when budgets tighten, regardless of their demonstrated educational value. [4]", "Taken together, the evidence supports a considerably more modest claim than public enthusiasm often assumes: musical training reliably develops musical and closely related skills, plausibly supports certain cognitive functions through mechanisms not yet fully specified, but does not straightforwardly transform general academic aptitude in the sweeping way popular narratives suggest. Whether more rigorously controlled longitudinal research will eventually identify robust far-transfer effects, or will instead confirm that music's primary educational value lies within its own domain, remains genuinely unresolved."], questions: [{ q: "According to the passage, why is it difficult to conclude that musical training directly causes the neural differences observed in musicians?", options: ["Neuroimaging studies have identified differences in auditory processing regions.", "Brains suited to sustained practice may have differed beforehand.", "Far transfer effects are too weak to support strong claims.", "Musical training always improves executive function regardless of prior ability."], answer: 1 }, { q: "The word \"compounds\" in paragraph 4 is closest in meaning to _______.", options: ["intensifies", "resolves", "duplicates", "components"], answer: 0 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["The Mozart effect study measured a brief spatial reasoning improvement.", "Musical training has now been proven to transform general intelligence.", "Music training's cognitive benefits are real but narrower than popular belief suggests.", "Every child who studies music will excel equally in mathematics."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a factor complicating claims about music's cognitive benefits?", options: ["Families enrolling children in music often have more household resources.", "Brains capable of sustained practice may differ before training starts.", "Far-transfer meta-analyses generally report small, inconsistent effect sizes.", "International testing agencies have banned music-based cognitive research funding."], answer: 3 }, { q: "The phrase \"This causal ambiguity\" in paragraph 3 refers to _______.", options: ["training-outcome uncertainty", "neuroimaging technology itself", "executive function research", "early training onset"], answer: 0 }, { q: "The word \"amplification\" in paragraph 5 is closest in meaning to _______.", options: ["reduction", "amplitude", "clarification", "exaggeration"], answer: 3 }, { q: "According to the passage, what problem does self-selection create for interpreting studies on music and academic achievement?", options: ["Apparent music-achievement links may really reflect pre-existing family advantages.", "Families enrolling children in music often have more household resources.", "Studies that control for income always find identical results.", "Self-selection makes musical training completely irrelevant to any outcome."], answer: 0 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Even a scientifically well-supported method, in other words, still depends on resources that not every school can provide.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }, { q: "What can be inferred about the future of research on music and cognition, based on the passage?", options: ["Longitudinal research will definitely prove far-transfer effects exist widely.", "Stronger academic performance will directly cause children to enjoy music more.", "The original Mozart effect study measured a brief performance improvement.", "Future research may need better long-term designs to settle far-transfer questions."], answer: 3 }, { q: "What is the author's overall attitude toward claims about music's cognitive benefits, as conveyed in the passage?", options: ["Measured and cautious, tempering popular enthusiasm with research nuance.", "Strongly dismissive that music education offers any real value at all.", "Fully convinced that music training reliably boosts general intelligence.", "Mildly critical of schools for underfunding all music programs equally."], answer: 0 }] },
    { title: "The Invisible Mountain: AI and the Growing Crisis of E-Waste", paragraphs: ["Public discussion of artificial intelligence's environmental footprint has concentrated overwhelmingly on the electricity and water consumed by data centers, a framing that, while accurate as far as it goes, obscures a second and comparatively under-examined consequence of the current AI hardware boom: an accelerating mountain of discarded computing equipment that grows largely outside public view, dispersed across corporate server rooms and, eventually, informal disposal sites rather than concentrated in any single visible location that might otherwise attract comparable scrutiny.", "Specialized AI processors, unlike the general-purpose chips that dominated computing for decades, are being replaced at a pace that some industry analysts describe as historically unprecedented , driven less by mechanical failure than by a competitive landscape in which each new generation of hardware offers substantial enough performance gains that operators judge continued use of older equipment economically irrational well before that equipment physically wears out. This dynamic , whatever its computational justification, compresses the useful lifespan of extraordinarily resource-intensive hardware into a fraction of what earlier computing generations typically achieved.", "It is this accelerated turnover, more than any single data center's operational footprint, that arguably deserves greater attention in assessments of AI's material consequences. A facility's water and electricity consumption, however substantial, is at least continuously measurable and increasingly subject to public disclosure requirements in several jurisdictions; the hardware discarded to make way for each successive generation, by contrast, largely disappears from public accounting once it leaves a data center's loading dock, resurfacing, if at all, in waste statistics that rarely distinguish AI-specific hardware from electronic waste more broadly.", "Recycling this hardware poses challenges considerably more severe than those associated with ordinary consumer electronics. Specialized AI chips typically combine dozens of different materials, including several rare earth elements, in configurations engineered for computational performance rather than eventual disassembly, meaning recovering these materials economically requires processes far more complex, and consequently far more expensive, than those developed for simpler consumer devices. Some recyclers report that current processing capacity, built primarily around smartphones and laptops, has not kept pace with the specific material composition and physical design of AI-optimized hardware now entering the waste stream in growing volumes.", "A number of researchers have proposed that artificial intelligence might eventually help address the very waste problem its own hardware demands have intensified, primarily through machine-vision systems capable of sorting mixed electronic waste streams more precisely than current manual or mechanical methods allow. Early pilot deployments report promising sorting accuracy improvements, though it remains genuinely unclear whether these efficiency gains, even if they scale successfully, could plausibly outpace the sheer volume of new AI hardware waste being generated, a question current pilot-scale evidence is not positioned to answer with any confidence.", "A substantial share of discarded computing hardware, AI-specific or otherwise, eventually travels to informal processing sites concentrated in a small number of countries, where workers, sometimes including children, extract valuable materials using methods that expose them to toxic combustion byproducts and heavy-metal contamination largely absent from regulated formal recycling facilities. Because AI hardware often contains a denser concentration of both valuable and hazardous materials than typical consumer electronics, its growing presence within this informal processing stream may plausibly intensify health and environmental risks already well documented in existing e-waste research, though quantifying that intensification specifically remains an open empirical question.", "Policy responses have so far struggled to keep pace with the hardware turnover driving this problem. [1] Extended producer responsibility frameworks, which require manufacturers to fund or manage the eventual disposal of the products they sell, exist in some jurisdictions but rarely account specifically for the unusual material composition and accelerated replacement cycles characteristic of AI-optimized hardware. [2] Enforcement gaps compound this design gap, since cross-border shipment of electronic waste, whether AI-related or not, remains difficult for any single jurisdiction to monitor comprehensively given the number of intermediary handlers a shipment may pass through. [3] Some policy analysts argue that hardware-specific regulatory categories will eventually be necessary, though others counter that existing e-waste frameworks, if adequately funded and enforced, could accommodate AI hardware without requiring an entirely new regulatory category. [4]", "Whether the AI industry's hardware turnover will be meaningfully addressed through some combination of regulatory reform, improved recycling technology, and voluntary industry commitment, or will instead continue accumulating largely outside public accounting as it has to date, is not a question current evidence allows anyone to answer with genuine confidence. What can be said with somewhat greater certainty is that the environmental conversation around artificial intelligence remains incomplete so long as it continues to overlook the hardware itself."], questions: [{ q: "According to paragraphs 2 and 3, why does the author suggest that AI hardware's rapid replacement deserves more attention than data center energy use?", options: ["Discarded hardware largely escapes the tracking that energy use already receives.", "Data centers no longer report any energy or water data.", "Each new hardware generation offers substantial enough performance gains to justify replacement.", "Every jurisdiction now requires full public disclosure of e-waste statistics."], answer: 0 }, { q: "The word \"unprecedented\" in paragraph 2 is closest in meaning to _______.", options: ["widely expected", "unmatched previously", "fairly affordable", "unpredictable"], answer: 1 }, { q: "Which of the following best expresses the main idea of the passage?", options: ["AI chips contain dozens of different rare earth materials.", "AI hardware waste has now been fully solved by recycling robots.", "AI's environmental impact debate overlooks its rapidly growing hardware waste problem.", "Every AI company currently ignores all forms of environmental responsibility."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a factor complicating AI hardware recycling?", options: ["AI chips combine dozens of materials in complex, hard-to-disassemble configurations.", "Current recycling capacity was built mainly around smartphones and laptops.", "Informal processing sites expose workers to toxic combustion byproducts.", "An outright international ban on all e-waste export shipments."], answer: 3 }, { q: "The phrase \"This dynamic\" in paragraph 2 refers to _______.", options: ["the fast chip-replacement pattern", "mechanical failure itself", "competitive hardware markets", "computational performance gains"], answer: 0 }, { q: "The word \"compound\" in paragraph 7 is closest in meaning to _______.", options: ["resolve", "replace", "make worse", "compost"], answer: 2 }, { q: "According to the passage, what does the passage suggest about AI hardware's presence in informal e-waste processing?", options: ["AI hardware's denser material mix may worsen existing e-waste health risks.", "AI hardware definitely causes far worse health outcomes than other e-waste.", "Workers, sometimes including children, extract materials using unsafe methods.", "Regulated formal recycling facilities pose greater risks than informal sites."], answer: 0 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Even where such frameworks technically apply, however, they were largely designed before AI-specific hardware existed in significant volume.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }, { q: "What can be inferred about the future trajectory of AI-related e-waste, based on the passage as a whole?", options: ["New regulations will certainly solve the AI e-waste problem within years.", "Improved recycling technology will directly cause AI hardware demand to fall.", "Early pilot deployments report promising sorting accuracy improvements already.", "AI hardware waste will likely keep growing without stronger policy or technology responses."], answer: 3 }, { q: "What is the author's overall attitude toward the AI hardware waste issue, as conveyed in the passage?", options: ["Strongly alarmed that AI hardware waste can never be recycled at all.", "Balanced and urgent, highlighting an overlooked but genuinely uncertain problem.", "Fully confident that AI-driven sorting robots will soon solve e-waste entirely.", "Mildly dismissive of concerns about informal e-waste processing sites."], answer: 1 }] },
  ] },
  { id: "rd-100", num: 100, title: "Đề 100", timeMin: 60, parts: [
    { title: "Discovering the Philippines: A Traveler's Guide to an Archipelago of Wonders", paragraphs: ["Stretching across more than 7,600 islands in the western Pacific Ocean, the Philippines offers one of the most geographically and culturally diverse travel experiences in Southeast Asia. From the terraced rice fields of the Cordillera mountains in the north, carved into steep hillsides by the Ifugao people over two thousand years ago, to the white sand beaches and crystal lagoons of Palawan in the south, the archipelago presents visitors with a landscape of extraordinary variety. Its warm climate, English-speaking population, and well-developed tourism infrastructure make it one of the most accessible destinations in the region for international travelers seeking both natural beauty and authentic cultural encounters.", "Manila, the country's bustling capital, is the most common entry point for international visitors and a destination of considerable historical interest in its own right. The walled city of Intramuros, built by Spanish colonizers in the sixteenth century, preserves the cobblestone streets, stone churches, and military fortifications of the colonial era within a compact area that can be explored on foot or by bicycle-powered rickshaw. Fort Santiago, located within Intramuros, served as a prison during the Japanese occupation of World War II and now houses a museum dedicated to the national hero José Rizal, whose writings and execution helped ignite the Philippine revolution against Spanish rule. Beyond its historical sites, Manila offers a dynamic contemporary urban experience, with world-class shopping malls, vibrant street food markets, and a nightlife scene that attracts visitors from across Asia.", "For many travelers, however, the primary draw of the Philippines lies beyond Manila — in the natural landscapes that have earned the country a reputation as one of the world's premier destinations for beach tourism and marine biodiversity. The island of Palawan, consistently ranked among the finest islands on Earth by international travel publications, is home to the Puerto Princesa Subterranean River National Park, a UNESCO World Heritage Site that features an underground river navigable by boat for several kilometers through cathedral-like limestone caves. The Bacuit Archipelago near El Nido offers dramatic limestone karst formations rising from turquoise waters, accessible by island-hopping boat tours that allow visitors to snorkel among coral reefs teeming with marine life.", "The Philippines is equally celebrated for its diving and snorkeling opportunities, with the Tubbataha Reef Natural Park in the Sulu Sea recognized as one of the most pristine coral ecosystems in the world. The Visayas region, comprising the central island group, is home to dive sites such as the waters around Malapascua Island — famous for reliable sightings of the thresher shark — and the underwater wrecks of Coron Bay in Palawan, where several Japanese warships sunk during World War II now serve as artificial reefs colonized by spectacular coral growth. The Philippines also hosts one of the world's most famous whale shark interaction sites at Oslob in Cebu, though this attraction has attracted controversy among conservationists who argue that the practice of feeding whale sharks to keep them near shore for tourist encounters disrupts the animals' natural behavior.", "The cultural dimension of travel in the Philippines is equally rewarding. The country's history of colonization — more than three centuries under Spain followed by several decades of American administration — has produced a culture that blends Malay, Spanish, Chinese, and American influences in ways that are uniquely Filipino. Festivals called fiestas, held in honor of patron saints across towns and cities throughout the year, offer visitors the chance to experience the exuberant local culture through music, dance, elaborate costumes, and street processions. The Ati-Atihan festival in Kalibo, often described as the Philippine equivalent of Brazil's Carnival, and the Sinulog festival in Cebu City are among the most spectacular, drawing hundreds of thousands of participants and spectators each year.", "Practical considerations for travelers include the best timing of visits. The Philippines has two broad seasons — the dry season from roughly November to May and the wet season from June to October — though regional variation is significant. The eastern seaboard of the country, including popular destinations such as Siargao Island, can receive heavy rainfall and occasional typhoons even during the months considered dry in other parts of the archipelago. Travelers planning beach-focused itineraries are generally advised to visit between December and April, when most of the country experiences calm seas, clear skies, and the favorable conditions that make beach and water activities most enjoyable."], questions: [{ q: "What is the main purpose of the passage?", options: ["To describe the Philippine festival calendar and explain why cultural tourism is more rewarding than beach tourism.", "To provide an overview of the Philippines as a travel destination, covering its natural, historical, cultural, and practical aspects.", "To warn international travelers about the environmental risks associated with mass tourism in the Philippine archipelago.", "To argue that the Philippines is superior to other Southeast Asian destinations for beach and diving tourism."], answer: 1 }, { q: "According to the passage, what is Intramuros and why is it historically significant?", options: ["It is a World War II battlefield on the outskirts of Manila where Filipino resistance fighters repelled the Japanese invasion.", "It is a natural cave system in Palawan where ancient Ifugao communities once lived, now preserved as a national monument.", "It is a cultural district in modern Manila famous for its street food markets and vibrant performing arts scene.", "It is a colonial-era walled city built by Spanish settlers in the sixteenth century, containing churches, fortifications, and cobblestone streets."], answer: 3 }, { q: "According to the passage, what feature makes Puerto Princesa Subterranean River National Park a UNESCO World Heritage Site?", options: ["It preserves the traditional rice terracing practices of the Ifugao people, recognized as living cultural heritage by UNESCO.", "It serves as a major nesting ground for endangered sea turtles and has been protected from development since the 1980s.", "It contains the largest coral reef in Southeast Asia and is home to several species of marine life found nowhere else on Earth.", "It features an underground river navigable by boat through limestone caves, making it a unique natural geological formation."], answer: 3 }, { q: "According to the passage, why has the whale shark interaction site at Oslob attracted criticism from conservationists?", options: ["Because feeding whale sharks to keep them near shore for tourists disrupts the animals' natural behavior patterns.", "Because the practice of touching whale sharks during tourist encounters causes stress that shortens the animals' lifespan.", "Because the site charges excessive fees that exclude local Filipino visitors and benefit only foreign tourism operators.", "Because the large number of tourist boats around the site has caused significant physical damage to the surrounding coral reef."], answer: 0 }, { q: "The word \"dramatic\" in paragraph 3 is closest in meaning to _______.", options: ["Commercially developed and equipped with facilities for large numbers of international tourists.", "Geologically unstable and potentially dangerous for inexperienced visitors without a local guide.", "Strikingly impressive and visually powerful, producing a strong effect on those who see them.", "Historically important and protected as part of the national heritage of the Philippine people."], answer: 2 }, { q: "The phrase \"this attraction\" in paragraph 4 refers to _______.", options: ["The Tubbataha Reef Natural Park, whose pristine coral ecosystem faces pressure from increasing numbers of dive tourists.", "The thresher shark sightings at Malapascua Island, which ecologists say are being disrupted by growing diver numbers.", "The underwater wrecks of Coron Bay, which conservationists argue should be preserved rather than promoted to divers.", "The whale shark interaction site at Oslob in Cebu, where tourists can encounter whale sharks that are kept nearby by feeding."], answer: 3 }, { q: "The word \"pristine\" in paragraph 4 is closest in meaning to _______.", options: ["Extremely remote and difficult to access, requiring expensive live-aboard dive boats to reach from the nearest island.", "Officially protected by international treaty and subject to strict visitor quotas enforced by the government.", "Heavily researched and well documented by marine biologists who have studied it for several decades.", "In its original and unspoiled condition, free from damage or significant human interference."], answer: 3 }, { q: "According to the passage, during which months are travelers generally advised to visit the Philippines for beach activities?", options: ["Between March and August, the window identified by tourism authorities as offering the best balance of good weather and lower crowds.", "Between December and April, when most of the country has calm seas, clear skies, and favorable conditions for water activities.", "Throughout the year, since the Philippines enjoys a tropical climate with consistently warm temperatures and little seasonal variation.", "From June to October, when the rainy season brings cooler temperatures that make outdoor activities more comfortable."], answer: 1 }, { q: "According to the passage, which of the following festivals is NOT mentioned by name in the passage?", options: ["The Pahiyas festival in Lucban, celebrated with elaborate rice wafer decorations displayed on the facades of houses.", "A fiesta held in honor of a patron saint, described as a type of local celebration found across the country throughout the year.", "The Sinulog festival in Cebu City, which draws hundreds of thousands of participants and spectators each year.", "The Ati-Atihan festival held in Kalibo, described as similar in spirit to Brazil's famous Carnival celebration."], answer: 0 }, { q: "What can be inferred from the passage about the author's attitude toward the whale shark tourism at Oslob?", options: ["The author presents the controversy objectively, noting the concerns raised by conservationists without personally condemning the attraction.", "The author strongly endorses the practice as a responsible form of wildlife tourism that educates visitors about marine conservation.", "The author suggests that the controversy has been exaggerated by conservationists and that the practice is largely harmless.", "The author implies that all whale shark tourism should be immediately banned and that Oslob represents irresponsible development."], answer: 0 }] },
    { title: "Children and Video Games: Navigating the Benefits and Risks", paragraphs: ["Few parenting debates of the past two decades have been as persistent or as emotionally charged as the question of how much time children should spend playing video games. From panicked headlines about addiction and violence to enthusiastic claims about cognitive enhancement and social skill development, the public discourse around children and gaming has oscillated between extremes that the available scientific evidence does not fully support in either direction. A more balanced and nuanced understanding of the relationship between children and video games — one that takes seriously both the genuine risks and the genuine benefits — requires moving beyond these competing narratives toward what the research actually shows.", "The potential benefits of age-appropriate video game play have been documented across a growing body of research. Studies in cognitive psychology have found that action video games, in particular, are associated with improvements in visual attention, spatial reasoning, and the ability to track multiple moving objects simultaneously. These skills have practical applications that extend beyond the screen: research has found correlations between action game experience and improved performance on tasks requiring precise visual-motor coordination, including certain surgical simulation exercises and air traffic control assessments. Strategy and puzzle games have been linked to gains in problem-solving ability, planning, and flexible thinking, while role-playing games with complex narratives may support vocabulary development and reading comprehension in younger players.", "The social dimension of gaming is also more nuanced than popular accounts often suggest. Online multiplayer games, which constitute a dominant form of play among school-age children and adolescents, require participants to communicate, coordinate strategies, manage shared resources, and navigate the social dynamics of teams composed of strangers. Research has found that children who engage in cooperative multiplayer games demonstrate stronger teamwork skills and a greater capacity for perspective-taking than those who primarily play alone. For socially anxious children, in particular, the relatively low-stakes social environment of an online game can serve as a scaffold — a supportive structure that allows them to practice social interaction and build confidence before transferring those skills to face-to-face settings.", "Nevertheless, the risks associated with excessive or poorly managed video game use among children are real and well-documented. The most straightforward concern involves displacement: time spent gaming is time not spent on physical activity, homework, face-to-face social interaction, and sleep — all of which are known to be essential for healthy child development. Studies have consistently found that children who spend more than two to three hours per day on screens are at elevated risk of sedentary lifestyle-related health problems, including obesity and associated metabolic conditions. Sleep disruption is a particularly significant concern, as the stimulating content of many games, combined with the blue light emitted by screens, can interfere with melatonin production and delay the onset of sleep, particularly when gaming continues close to bedtime.", "The relationship between violent video games and aggressive behavior in children has been among the most extensively studied questions in this field, and also among the most contested. A substantial body of research has found short-term increases in aggressive thoughts and feelings following exposure to violent game content. However, the evidence for a link between violent game play and actual violent behavior in real life is considerably weaker, and a number of studies have found no significant relationship after controlling for pre-existing personality factors and family environment. The American Psychological Association has periodically revised its position on this issue, reflecting the ongoing scientific uncertainty. Most researchers in this area now take a nuanced view: violent content is unlikely to be a primary cause of violent behavior, but it may be one contributing factor among many for children who are already at elevated risk due to other circumstances in their lives.", "Parental guidance and household rules around gaming appear to play a significant role in determining whether a child's gaming experience is primarily beneficial or harmful. Research has consistently found that children whose parents actively engage with their gaming — asking about games, playing together, setting consistent time limits, and monitoring content ratings — show better outcomes than those whose gaming is unsupervised. The most effective approach, according to multiple studies, is not prohibition but collaborative regulation: involving children in the process of setting fair rules, discussing the reasons behind content restrictions, and modeling healthy technology use habits within the family. The introduction of structured gaming-free periods, particularly in the hour before bedtime and during mealtimes, has been shown to improve sleep quality and family cohesion without requiring children to abandon gaming entirely.", "The challenge for parents, educators, and policymakers is to resist the temptation to adopt either an alarmist or a permissive stance toward children's gaming, and instead to develop the media literacy and critical thinking skills that allow young people to engage with digital entertainment thoughtfully and on their own terms. Video games, like books, television, and social media, are a feature of the information environment in which children grow up — one that is neither inherently harmful nor inherently beneficial, but whose impact depends critically on the conditions under which it is encountered and the guidance available to young people as they navigate it."], questions: [{ q: "What is the main purpose of the passage?", options: ["To summarize the scientific debate about violent video games and explain why research findings have been inconsistent.", "To present a balanced view of the evidence on children and gaming, acknowledging both benefits and risks while emphasizing the role of guidance.", "To warn parents that video games are primarily harmful to children and should be strictly limited or banned at home.", "To argue that the cognitive benefits of video games outweigh the social and health risks and that restrictions are largely unnecessary."], answer: 1 }, { q: "According to the passage, which cognitive skills are specifically associated with playing action video games?", options: ["Gains in visual attention, spatial reasoning, and the ability to track multiple moving objects simultaneously.", "Stronger long-term memory consolidation, better impulse control, and faster academic test performance.", "Enhanced reading comprehension, expanded vocabulary, and stronger narrative understanding in younger players.", "Improved planning ability, faster mathematical computation, and better performance in language examinations."], answer: 0 }, { q: "According to the passage, how can online multiplayer games benefit socially anxious children in particular?", options: ["They provide a lower-stakes environment for practicing social interaction that can help build confidence for face-to-face situations.", "They expose children to a wider range of social perspectives that challenge the narrow worldview associated with social anxiety.", "They allow children to form friendships with peers who share similar anxieties, reducing the sense of isolation they feel at school.", "They offer rewards for successful social engagement that gradually retrain anxious children to associate interaction with positive outcomes."], answer: 0 }, { q: "According to the passage, how much daily screen time do studies associate with elevated health risks for children?", options: ["Over four hours daily, a threshold above which researchers say cognitive and social development begins to suffer.", "Any amount exceeding thirty minutes on school nights, according to guidelines from major pediatric health organizations.", "More than one hour per day, particularly when gaming occurs in the evening hours before bedtime.", "More than two to three hours per day, at which point children face elevated risk of sedentary lifestyle-related conditions."], answer: 3 }, { q: "The word \"flexible\" in paragraph 2 is closest in meaning to _______.", options: ["Collaborative and oriented toward working with others to arrive at solutions that benefit the whole group.", "Able to adapt and shift approaches readily rather than being locked into a single rigid way of thinking.", "Technically advanced and requiring the application of previously learned knowledge in new and complex situations.", "Creative and imaginative, producing original solutions that go beyond conventional problem-solving strategies."], answer: 1 }, { q: "The word \"scaffold\" in paragraph 3 (\"an online game can serve as a scaffold \") is used to mean _______.", options: ["A temporary barrier that prevents children from engaging with challenges that are too socially demanding for their current skill level.", "A competitive framework that motivates children to improve their social skills by comparing their performance to that of peers.", "A formal assessment tool used by teachers and therapists to measure a child's progress in developing social communication skills.", "A supportive structure that enables children to practice and develop skills in a safer environment before applying them elsewhere."], answer: 3 }, { q: "The word \"interfere\" in paragraph 4 is closest in meaning to _______.", options: ["To disrupt or obstruct a natural process, preventing it from functioning normally as it otherwise would.", "To moderately slow down a process in ways that are noticeable but not clinically significant for healthy children.", "To completely destroy a biological process by permanently altering the hormone systems responsible for regulating it.", "To temporarily pause a physical function that will resume without difficulty once the disruptive stimulus is removed."], answer: 0 }, { q: "According to the passage, what approach to managing children's gaming do multiple studies identify as most effective?", options: ["Collaborative regulation — involving children in setting fair rules, explaining restrictions, and modeling healthy technology habits.", "Complete prohibition of gaming on school nights combined with generous time allowances on weekends and school holidays.", "Delegating supervision responsibilities to schools, which are better equipped than parents to monitor gaming content and duration.", "Allowing children unrestricted access to games of their choosing while monitoring their mood and academic performance closely."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a parental practice associated with better outcomes for children who game?", options: ["Playing video games together with children as a shared family activity.", "Setting consistent limits on the amount of time children spend gaming each day.", "Asking children about the games they play and showing genuine interest in their gaming experience.", "Enrolling children in digital literacy programs offered by schools or community organizations."], answer: 3 }, { q: "What can be inferred from paragraph 5 about the author's view of violent video games and children's behavior?", options: ["The author implies that violent games are the primary driver of aggressive behavior in children and should be banned for all age groups.", "The author concludes that violent video games are definitively harmless and that parental concern about them is entirely unfounded.", "The author suggests that violent game content is unlikely to be a main cause of violence but may be one of several contributing factors for at-risk children.", "The author argues that because research findings are inconsistent, no conclusions can be drawn and parents should make their own judgment."], answer: 2 }] },
    { title: "Ancient Healing in the Modern World: Traditional Medicine Systems and Their Place in Contemporary Healthcare", paragraphs: ["Across virtually every human civilisation, communities developed sophisticated frameworks for understanding illness and restoring health long before the emergence of laboratory-based medicine. These frameworks — encompassing herbal therapies, physical manipulation, dietary regulation, and spiritual practice — have persisted for thousands of years and continue to be practised by hundreds of millions of people worldwide. In an era defined by pharmaceutical innovation and evidence-based clinical protocols, the question of how traditional medicine systems fit within modern healthcare is no longer merely academic. Governments, international health bodies, and researchers are increasingly being asked to take a considered position on practices whose origins predate the scientific method by millennia. [1]", "Among the most widely recognised traditional systems is Ayurveda, which originated on the Indian subcontinent and is estimated to be at least three thousand years old. Rooted in the concept of balance among three fundamental bodily energies known as doshas, Ayurveda employs a broad therapeutic repertoire that includes herbal preparations, oil-based body treatments, dietary prescriptions, breathing exercises, and yoga — a discipline that has itself achieved global popularity as both a fitness practice and a stress-management tool. Its integration into clinical settings in several countries reflects a growing institutional recognition that certain components of Ayurvedic practice may offer measurable health benefits, particularly in the management of chronic conditions such as arthritis, metabolic disorders, and anxiety.", "Traditional Chinese Medicine, or TCM, represents another major system whose influence extends far beyond its country of origin. Built on theoretical foundations that include the circulation of a life force known as qi through channels called meridians, TCM encompasses acupuncture, herbal prescriptions, cupping therapy, and dietary therapy. Acupuncture in particular has attracted sustained scientific attention: systematic reviews of clinical trial data have found evidence supporting its use for the management of chronic pain, postoperative nausea, and certain headache disorders, though researchers continue to debate the extent to which its effects exceed those of sham procedures. [2] This methodological complexity — the difficulty of designing a convincing placebo for a physically administered treatment — has made it challenging to apply standard randomised controlled trial frameworks to the evaluation of acupuncture and similar practices.", "Beyond South and East Asia, other traditional healing traditions have developed independently and exert considerable influence over local health behaviours. These include Unani medicine, which traces its origins to ancient Greek humoral theory and was subsequently elaborated in the Islamic world; the diverse plant-based healing practices of indigenous communities across Africa, the Americas, and the Pacific; and the spiritual healing systems of various shamanic traditions. The World Health Organization's Traditional Medicine Strategy, most recently updated in 2019, estimated that approximately eighty percent of the global population relies on traditional medicine as a primary or complementary source of healthcare — a figure that underscores the scale of the phenomenon and the inadequacy of frameworks that dismiss it as mere superstition.", "The mainstream scientific community's engagement with traditional medicine has evolved from outright scepticism toward a more differentiated approach. Ethnobotanical research — the systematic study of plant-based knowledge held by indigenous and traditional communities — has yielded a number of pharmacologically significant discoveries. Artemisinin, derived from the sweet wormwood plant used in Chinese herbal medicine and now the cornerstone of global malaria treatment, represents perhaps the most celebrated example of how traditional knowledge can serve as a productive lead for drug development. [3] Similarly, compounds derived from Ayurvedic plants such as Boswellia and turmeric have attracted pharmaceutical interest for their anti-inflammatory properties, prompting clinical trials in several countries.", "However, enthusiasm for integrating traditional medicine into formal health systems must be tempered by acknowledgement of genuine risks. Some herbal preparations contain biologically active compounds that can interact adversely with pharmaceutical drugs, cause organ toxicity at high doses, or vary in potency depending on the conditions of cultivation and preparation. Regulatory frameworks in many countries remain poorly equipped to ensure the quality, safety, and standardisation of traditional remedies sold commercially. [4] Furthermore, the theoretical frameworks underlying some traditional systems — including concepts such as qi circulation and dosha imbalance — have no direct equivalents in biomedical science, raising unresolved questions about whether these systems are best evaluated on their own conceptual terms, through the lens of conventional clinical research, or through some hybrid methodology yet to be fully developed.", "What seems increasingly clear is that a blanket endorsement or a blanket rejection of traditional medicine serves neither scientific rigour nor public health. The most productive path forward may lie in disaggregating these diverse systems into their component practices, subjecting each to appropriately designed research, and developing regulatory and clinical frameworks capable of incorporating what is safe and effective while protecting patients from what is not."], questions: [{ q: "What is the main argument of this passage?", options: ["Scientific research has conclusively proven that traditional medicine practices are ineffective and potentially dangerous for patients.", "Traditional medicine systems should be fully integrated into national healthcare systems without further evaluation or modification.", "Traditional medicine systems merit serious engagement from researchers and policymakers, but require careful, practice-by-practice evaluation.", "The global reliance on traditional medicine is primarily a consequence of inadequate access to modern pharmaceutical healthcare."], answer: 2 }, { q: "What is the author's primary purpose in paragraph 5?", options: ["To suggest that Ayurvedic and Chinese herbal medicines are already as effective as modern pharmaceutical treatments.", "To explain why ethnobotanical research has largely failed to produce useful compounds for the treatment of infectious diseases.", "To argue that pharmaceutical companies should acquire the intellectual property rights of traditional healing communities.", "To demonstrate that traditional medical knowledge can serve as a productive source of scientifically validated drug discoveries."], answer: 3 }, { q: "According to the passage, which of the following correctly describes the therapeutic approach of Ayurveda?", options: ["It focuses primarily on surgical interventions and the use of mineral-based compounds to restore bodily balance.", "It relies exclusively on herbal preparations and dietary regulation, excluding physical and breathing-based practices.", "It employs a combination of herbal remedies, oil treatments, dietary guidance, breathing exercises, and yoga.", "It is based entirely on yoga and meditation, which are used to correct imbalances among the three doshas."], answer: 2 }, { q: "According to the passage, why is artemisinin considered a significant example in the context of this passage?", options: ["It demonstrates that Ayurvedic plant compounds can be more effective than synthetic drugs in treating inflammatory disorders.", "It shows that Chinese herbal medicine has been scientifically validated as superior to Western pharmaceutical approaches to malaria.", "It proves that ethnobotanical research is the only reliable method for identifying new compounds for pharmaceutical development.", "It illustrates how knowledge from a traditional healing system led to the development of a major modern medical treatment."], answer: 3 }, { q: "According to the passage, what proportion of the global population relies on traditional medicine as a primary or complementary healthcare source?", options: ["Fewer than sixty percent, a figure that researchers argue reflects declining interest in traditional practices among younger populations", "Approximately fifty percent, according to the most recent edition of the World Health Organization's Traditional Medicine Strategy", "More than ninety percent in lower-income countries, compared with fewer than thirty percent in high-income nations", "Around eighty percent, a figure cited in the World Health Organization's 2019 Traditional Medicine Strategy report"], answer: 3 }, { q: "The word \"repertoire\" in paragraph 2 is closest in meaning to _______.", options: ["the historical record of medical procedures documented and preserved within a particular cultural tradition", "a theoretical framework used to explain the relationship between bodily energies and physical health outcomes", "a set of restrictions imposed on practitioners regarding which treatments may be used for specific conditions", "the range of techniques and treatments that a system or practitioner has available to apply in a given context"], answer: 3 }, { q: "The word \"tempered\" in paragraph 6 is closest in meaning to _______.", options: ["strengthened and reinforced by additional evidence drawn from clinical trials conducted in multiple countries", "moderated and restrained by the recognition of real risks that must be weighed against potential benefits", "redirected and refocused toward a narrower set of practices that have already been validated through rigorous research", "challenged and undermined by a growing body of evidence suggesting that integration carries unacceptable dangers"], answer: 1 }, { q: "The word \"These\" in paragraph 4 refers to _______.", options: ["the theoretical foundations underlying Unani medicine, which trace their origins to ancient Greek humoral theory", "the diverse plant species used by indigenous communities across Africa, the Americas, and the Pacific for medicinal purposes", "the local health behaviours of communities in South and East Asia that have been influenced by traditional Chinese medicine", "the traditional healing traditions outside South and East Asia, including Unani medicine, indigenous plant-based practices, and shamanic systems"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a risk or challenge associated with traditional medicine?", options: ["The potency of traditional remedies can vary depending on the conditions under which the plants are cultivated and prepared.", "Practitioners of traditional medicine in rural areas frequently lack the formal training required to diagnose serious diseases.", "Some herbal preparations may interact adversely with pharmaceutical drugs that patients are simultaneously taking.", "The theoretical concepts of some traditional systems have no direct equivalents in mainstream biomedical science."], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'The challenge of isolating active compounds from complex multi-ingredient formulations further complicates the translation of traditional knowledge into standardised pharmaceutical products.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 2 }] },
    { title: "The Co-evolution of Language and the Human Brain", paragraphs: ["Of all the capacities that distinguish Homo sapiens from other animals, none has attracted more sustained scientific fascination than language. The ability to encode complex meaning into sequences of arbitrary sounds, transmit those sequences to other minds, and reconstruct their meaning with sufficient fidelity to enable coordinated action, cultural transmission, and abstract reasoning represents an achievement of staggering biological complexity. [1] Understanding how this capacity came to exist requires engagement with one of the most contested and methodologically demanding questions in the life sciences: did the human brain evolve in order to produce language, or did the demands of language itself reshape the brain over evolutionary time? Increasingly, researchers propose that neither framing is adequate, and that language and the brain are best understood as having co-evolved through a dynamic, mutually constitutive process spanning hundreds of thousands of years.", "The neurological infrastructure supporting language in modern humans is both specialised and distributed. Broca's area, located in the left inferior frontal gyrus, has long been associated with speech production and grammatical processing, while Wernicke's area, situated in the posterior superior temporal gyrus, is implicated in language comprehension. These regions are connected by a white matter tract known as the arcuate fasciculus, the integrity of which appears to be critical for the fluent integration of production and comprehension. Comparative neuroanatomical research has revealed that while homologues of Broca's and Wernicke's areas exist in non-human primates, the arcuate fasciculus in humans is significantly more developed than in our closest living relatives, suggesting that the elaboration of this connectivity may have been a pivotal step in the emergence of fully modern language capacity. [2]", "The evolutionary timeline of language remains deeply uncertain, in part because language itself leaves no direct fossil record. Researchers must instead rely on indirect proxies: the morphology of the vocal tract and hyoid bone, endocranial casts that preserve the surface topography of ancient brains, and the archaeological record of symbolic behaviour such as ochre use, cave art, and the production of ornamental objects. The hyoid bone — a small, horseshoe-shaped structure that anchors the muscles of the tongue and larynx — has received particular attention. A hyoid recovered from a Neanderthal individual at Kebara Cave in Israel was found to be morphologically indistinguishable from those of anatomically modern humans, fuelling debate about whether Neanderthals possessed at least some degree of vocal language capacity. [3]", "Genetic research has added further complexity to this picture. The discovery that a specific variant of the FOXP2 gene — long dubbed the \"language gene\" despite the considerable oversimplification this label implies — is shared between modern humans and Neanderthals has been interpreted by some researchers as evidence of a common capacity for spoken language in both lineages. However, the function of FOXP2 extends well beyond language: it regulates motor learning circuits involved in the precise orofacial movements required for articulate speech, and mutations in the human version of this gene produce severe difficulties with both speech and broader grammatical processing. Its role in language evolution is therefore best understood as one component within a much broader genetic architecture, rather than as a singular causative agent.", "Perhaps the most theoretically provocative dimension of language evolution research concerns the relationship between language and thought itself. The nativist position, most influentially articulated by Noam Chomsky, holds that the human mind is equipped with a biologically endowed language acquisition device — an innate grammatical faculty that constrains the structural forms that any human language can take. On this view, the universality of certain grammatical properties across typologically diverse languages reflects the architecture of the human genome rather than cultural convergence. Critics of this position, including proponents of usage-based and emergentist theories, argue that language structure arises from the interaction of general cognitive capacities — such as pattern recognition, analogy, and social pragmatics — with the statistical regularities present in the linguistic input that children encounter during development.", "The debate between nativist and emergentist positions has significant implications for how we understand the relationship between language and cognition more broadly. If grammatical structure is largely innate, then language is to some degree a self-contained cognitive module, evolved for specific communicative purposes and relatively insulated from other cognitive systems. If, on the other hand, language emerges from the application of domain-general cognitive tools to communicative problems, then the evolution of language cannot be cleanly separated from the broader expansion of human cognitive capacity — including enhanced working memory, theory of mind, and the capacity for hierarchical planning — that distinguishes our species from all others. [4]", "Most contemporary researchers in linguistics, cognitive neuroscience, and evolutionary biology would likely endorse a position somewhere between these poles. Language is neither a fully autonomous biological module nor a simple by-product of general intelligence, but rather a capacity that is uniquely enabled by a constellation of biological, cognitive, and social factors that came together, perhaps quite rapidly in evolutionary terms, in the lineage leading to modern Homo sapiens. What drove this convergence — whether it was the selective pressure of social coordination, the demands of tool manufacture and teaching, or some combination of ecological and cultural forces — remains one of the most productively unresolved questions in the study of human origins."], questions: [{ q: "Which of the following best captures the central claim that the passage develops across all seven paragraphs?", options: ["The human brain evolved its language capacity independently of cultural or social pressures, as a result of purely genetic mutations in a small number of key genes.", "Language and the human brain co-evolved through a mutually shaping process, and understanding this process requires integrating evidence from neuroscience, genetics, and evolutionary biology.", "The evolutionary origins of language remain entirely unknowable because the absence of a fossil record makes all proposed timelines and mechanisms purely speculative.", "Nativist theories of language acquisition have been conclusively validated by genetic evidence, confirming that grammar is a biologically encoded and species-specific faculty."], answer: 1 }, { q: "What is the author's attitude toward the debate between nativist and emergentist positions on language?", options: ["Strongly sympathetic to emergentist theories, since domain-general cognitive tools provide a more parsimonious explanation of language acquisition.", "Dismissive of both positions, arguing that neither has produced sufficient empirical evidence to merit serious consideration in contemporary research.", "Firmly aligned with the nativist position, on the grounds that the universality of grammatical structures across languages constitutes compelling biological evidence.", "Cautiously balanced, suggesting that the most defensible account integrates aspects of both positions rather than endorsing either extreme."], answer: 3 }, { q: "The word \"Its\" in paragraph 4 refers to _______.", options: ["the FOXP2 gene variant shared between modern humans and Neanderthals, whose role in language is part of a broader genetic architecture", "the \"language gene\" label that has been applied to FOXP2 despite the considerable oversimplification this characterisation implies", "the Neanderthal individual at Kebara Cave whose hyoid bone morphology reignited debate about archaic human vocal capacity", "the motor learning circuit that regulates the orofacial movements required for producing articulate speech in modern humans"], answer: 0 }, { q: "According to the passage, what makes the arcuate fasciculus particularly significant in the context of language evolution?", options: ["It is a neural structure found exclusively in Homo sapiens and is entirely absent in all non-human primate species studied to date.", "It is substantially more elaborated in humans than in our closest primate relatives, suggesting it was pivotal in the emergence of full language capacity.", "It is the only white matter tract in the human brain whose integrity has been directly linked to the acquisition of a second language in adulthood.", "It connects Broca's area and Wernicke's area, and damage to it produces an inability to produce speech while leaving comprehension fully intact."], answer: 1 }, { q: "According to the passage, why did the discovery of the Neanderthal hyoid bone at Kebara Cave generate scientific debate?", options: ["Because it was found alongside cave art and ochre deposits that suggested Neanderthals had developed advanced symbolic communication systems.", "Because its morphology was indistinguishable from that of anatomically modern humans, raising the possibility that Neanderthals could produce vocal language.", "Because it was the oldest hyoid bone ever recovered, predating all previously known specimens from both archaic and modern human lineages.", "Because it was structurally identical in shape to the hyoid bones of chimpanzees, casting doubt on earlier theories of Neanderthal vocal ability."], answer: 1 }, { q: "Based on paragraphs 4 and 5 taken together, what can be inferred about the relationship between FOXP2 and the origins of human language?", options: ["FOXP2 is unrelated to language capacity and its association with speech difficulties in humans with mutations reflects a purely coincidental genetic link.", "FOXP2 provides definitive evidence that Neanderthals possessed the same full range of grammatical and communicative abilities as anatomically modern humans.", "FOXP2 plays a role in language-related motor learning but is one element within a wider genetic and cognitive architecture, making it neither a sole cause nor an irrelevant factor.", "FOXP2 is a sufficient explanation for the emergence of language, since its shared presence in humans and Neanderthals confirms that both species had equivalent linguistic ability."], answer: 2 }, { q: "The word \"morphologically\" in paragraph 3 is closest in meaning to _______.", options: ["with regard to the functional role that the structure performs within the broader musculoskeletal system of the body", "in terms of its chemical composition and the mineral density recorded across the surface of the recovered bone", "in terms of its physical shape, size, and structural form as observable through anatomical examination", "with respect to the geological context and stratigraphic layer in which the fossil specimen was originally excavated"], answer: 2 }, { q: "The word \"nativist\" in paragraph 5 is closest in meaning to _______.", options: ["relating to the claim that different human languages reflect fundamentally different cognitive architectures in the minds of their speakers", "relating to the argument that language evolved primarily in response to the social and communicative demands of early human communities", "relating to the position that certain core grammatical properties of language are biologically innate and shared across all human populations", "relating to the view that language structures emerge gradually from the interaction of general cognitive capacities with environmental input during development"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as an indirect proxy used by researchers to study the evolutionary timeline of language?", options: ["The morphology of the vocal tract and hyoid bone in fossil specimens of archaic human species", "Endocranial casts that preserve the surface topography of ancient hominin brain cases", "Comparative studies of the vocalisations produced by chimpanzees and other great apes", "The archaeological record of symbolic behaviours such as cave art and the use of ochre"], answer: 2 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Recent palaeogenomic analyses have added a further layer of evidence to this debate by enabling direct comparison of gene expression patterns between modern humans and reconstructed archaic genomes.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 2 }] },
  ] },
];
